-- 1. Modern SQL-Standard Identity Column
CREATE TABLE invoices (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    total_amount NUMERIC(10, 2)
);

-- 2. Native UUIDv4 Primary Key
CREATE TABLE accounts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name VARCHAR(100)
);

CREATE TABLE invoices (
    -- ALWAYS: inserts must not supply an id
    id    BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    total NUMERIC(10,2) NOT NULL
);

INSERT INTO invoices (total) VALUES (10.00);

-- Explicit value is rejected
INSERT INTO invoices (id, total) VALUES (5, 10.00);
-- ERROR: cannot insert a non-DEFAULT value into column "id"

-- But you can override deliberately (useful for data migrations)
INSERT INTO invoices (id, total) OVERRIDING SYSTEM VALUE VALUES (5, 10.00);

-- Inspect and reset the backing sequence
SELECT pg_get_serial_sequence('invoices', 'id');
SELECT setval(pg_get_serial_sequence('invoices','id'), (SELECT max(id) FROM invoices));

-- Identity also supports a custom sequence
CREATE TABLE t (id BIGINT GENERATED BY DEFAULT AS IDENTITY
                (START WITH 1000 INCREMENT BY 10) PRIMARY KEY);

SHOW server_version_num;

-- PostgreSQL 18+ ships uuidv7() in core
CREATE TABLE accounts_v7 (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    name TEXT NOT NULL
);

-- Before PG 18: generate in the application (e.g. Java 20+, .NET 9, many libs),
-- or use the pg_uuidv7 extension
CREATE TABLE accounts_v4 (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   -- v4, random
    name TEXT NOT NULL
);

-- Compare insert locality: v7 keys sort by time
SELECT id, id::text AS as_text FROM accounts_v7 ORDER BY id LIMIT 5;
